// Konyha (fuel/1), Trendek (fuel/2) and Kiegészítők (fuel/3) full-page renderers.
import { createRecipes, addRecipe, createPantry, addPantryItem, removePantryItem, createStack, toggleIntake, stackProgress, addStackItem, stackZones, weekData, weekSummary, longHorizon, patterns } from './fuel-state.js';
import { openFoodFixed } from './food.js';
import { energyDetailHtml, dimGlassHtml } from './fuel-dashboard.js';
import { icon, safe, toast, react } from './nap.js';
const fmt=v=>Math.round(v).toLocaleString('hu-HU');
let recipes=createRecipes(),pantry=createPantry(),stack=createStack(),week='current',callbacks;

// --- Konyha ---------------------------------------------------------------
const capture=(attr,glyphName,title,sub)=>`<button class="konyha-capture" ${attr}><span class="konyha-capture-art">${icon(glyphName)}</span><span><strong>${title}</strong><small>${sub}</small></span><b>＋</b></button>`;
const recipeRow=r=>`<button class="konyha-row" data-recipe="${r.id}">${icon('bowl')}<span><strong>${safe(r.name)}</strong><small>${r.slot} · ${fmt(r.kcal)} kcal · ${fmt(r.p)} g fehérje</small></span><b>${r.fit==null?'✨ számolódik':`✨ ${r.fit.toLocaleString('hu-HU')}`}</b></button>`;
const pantryRow=k=>`<button class="konyha-row" data-pantry="${k.id}">${icon(k.kind==='supp'?'gem':'stack')}<span><strong>${safe(k.name)}</strong><small>${safe(k.amount)}${k.dose?` · ${safe(k.dose)}`:''} · ${safe(k.source)}</small></span><b>↗</b></button>`;
const door=(sub,art,title,copy,count)=>`<button class="konyha-door" data-subroute="${sub}"><span class="konyha-capture-art">${icon(art)}</span><span><strong>${title}</strong><small>${copy}</small></span><b><strong>${count}</strong>↗</b></button>`;
function konyha(){return `${capture('data-konyha-recipe','book','Recept mentése','Műhely · link · kézzel')}${capture('data-konyha-pantry','stack','Új elem a kamrába','Fotó a címkéről · link · katalógus')}<div class="lf-section"><h2>A gyűjteményeid</h2></div>${door('receptek','book','Receptek','A saját könyvtárad, mezo-pontokkal',`${recipes.length}`)}${door('kamra','stack','Kamra','Ami a polcodon van',`${pantry.length}`)}<p class="food-note">A gyors mentés ide, fent történik — a böngészés a saját oldalán.</p>`;}
const subHead=(title,count)=>`<div class="konyha-subhead"><button data-route="fuel/1" aria-label="Vissza a Konyhára">‹</button><span><small>KONYHA</small><strong>${title}</strong></span><b>${count}</b></div>`;
const receptekPage=()=>`${subHead('Receptek',`${recipes.length} RECEPT`)}<div class="konyha-list">${recipes.map(recipeRow).join('')}</div><p class="food-note">Koppints egy receptre: részletek, naplózás, iterálás a Műhelyben.</p>`;
const kamraPage=()=>`${subHead('Kamra',`${pantry.length} ELEM`)}<div class="konyha-list">${pantry.map(pantryRow).join('')}</div><p class="food-note">Koppints egy elemre: részletek, naplózás, levétel a polcról.</p>`;
const workshopSheet=()=>`<h2 class="sheet-title">Recept mentése</h2><div class="lf-chips" data-recipe-tabs>${[['muhely','✨ Műhely'],['link','Link'],['kezi','Kézzel']].map(([v,l],i)=>`<button data-recipe-tab="${v}" aria-pressed="${i===0}">${l}</button>`).join('')}</div><div data-recipe-pane="muhely"><div class="chat-bubble">Mit főzzünk ki? Mondd a célt, és összerakok egy első változatot.<span class="chat-time">MŰHELY · DEMÓ</span></div><div class="lf-chips">${['Fehérjében erős','Edzés utáni','Esti, könnyű'].map(g=>`<button data-workshop-goal="${safe(g)}">${g}</button>`).join('')}</div><div id="workshop-result"></div></div><div data-recipe-pane="link" hidden><form id="recipe-link-form"><label class="lf-field">Recept linkje<input name="url" type="url" placeholder="https://…" required></label><button class="sheet-action">Kinyerem a receptet ✦</button></form><div id="recipe-link-result"></div></div><div data-recipe-pane="kezi" hidden><form id="recipe-manual-form"><label class="lf-field">Név<input name="name" required placeholder="Pl. Lencsés curry"></label><label class="lf-field">Kalória / adag<input name="kcal" type="number" min="1" max="3000" required value="610"></label><label class="lf-field">Fehérje (g)<input name="p" type="number" min="0" max="300" required value="31"></label><button class="sheet-action">Mentem a receptet ✓</button></form></div><p class="food-note">Demó: a Műhely és a link-kinyerés előre megírt mintát ad, valódi AI-hívás nélkül.</p>`;
const pantrySheet=()=>`<h2 class="sheet-title">Új elem a kamrába</h2><div class="lf-chips" data-pantry-tabs>${[['foto','📷 Fotó'],['link','Link'],['kezi','Kézzel'],['katalogus','Katalógus']].map(([v,l],i)=>`<button data-pantry-tab="${v}" aria-pressed="${i===0}">${l}</button>`).join('')}</div><div data-pantry-pane="foto"><div class="food-finder small"><span></span><span></span><span></span><span></span><p>CÍMKE A KERESŐBEN · DEMÓ</p></div><button class="sheet-action" data-pantry-shot>Exponálás — minta: túró 250 g</button><div id="pantry-photo-result"></div></div><div data-pantry-pane="link" hidden><form id="pantry-link-form"><label class="lf-field">Termék linkje<input name="url" type="url" placeholder="https://…" required></label><button class="sheet-action">Kinyerem az adatokat ✦</button></form><div id="pantry-link-result"></div></div><div data-pantry-pane="kezi" hidden><form id="pantry-manual-form"><label class="lf-field">Név<input name="name" required placeholder="Pl. Mandula"></label><label class="lf-field">Mennyiség<input name="amount" placeholder="Pl. 200 g"></label><label class="lf-field">Típus<select name="kind"><option value="food">Étel</option><option value="supp">Kiegészítő</option></select></label><button class="sheet-action">Felveszem ✓</button></form></div><div data-pantry-pane="katalogus" hidden><div class="konyha-list">${[['Zabpehely','372 kcal / 100 g'],['Mandula','579 kcal / 100 g'],['Skyr','63 kcal / 100 g']].map(([n,s])=>`<button class="konyha-row" data-catalog-add="${safe(n)}">${icon('stack')}<span><strong>${n}</strong><small>${s} · közös katalógus</small></span><b>＋</b></button>`).join('')}</div></div><p class="food-note">Demó: a fotó- és link-kinyerés mintaeredményt ad. Kétszeri hozzáadás nem duplikál.</p>`;
function recipeSheet(r){return `${icon('bowl')}<h2 class="sheet-title">${safe(r.name)}</h2><p class="sheet-sub">${safe(r.note)}</p><div class="lf-stats"><div><strong>${fmt(r.kcal)}</strong><small>kcal / adag</small></div><div><strong>${fmt(r.p)} g</strong><small>fehérje</small></div><div><strong>${r.fit==null?'—':`✨ ${r.fit.toLocaleString('hu-HU')}`}</strong><small>mezo-pont</small></div></div><div class="konyha-lines">${r.lines.map(l=>`<p>· ${safe(l)}</p>`).join('')||'<p>· A hozzávalók a demóban nem részletezettek.</p>'}</div><button class="sheet-action" data-recipe-log="${r.id}">Ma ettem ilyet — naplózom ✓</button><button class="sheet-action secondary" data-workshop-iterate="${r.id}">✨ Iterálás a Műhelyben</button>`;}
function pantryItemSheet(k){return `${icon(k.kind==='supp'?'gem':'stack')}<h2 class="sheet-title">${safe(k.name)}</h2><p class="sheet-sub">${safe(k.amount)}${k.dose?` · ${safe(k.dose)}`:''} · forrás: ${safe(k.source)}</p>${k.kcal100?`<div class="lf-stats"><div><strong>${fmt(k.kcal100)}</strong><small>kcal / 100 g</small></div><div><strong>${fmt(k.p100)} g</strong><small>fehérje / 100 g</small></div></div>`:''}${k.kind==='food'&&k.kcal100?`<button class="sheet-action" data-pantry-log="${k.id}">Ettem belőle — naplózom ✓</button>`:''}<button class="sheet-action secondary" data-pantry-remove="${k.id}">Leveszem a polcról</button>`;}

// --- Trendek --------------------------------------------------------------
function weekBars(w){const max=2900;return `<div class="week-bars" role="img" aria-label="A hét napjai a kerethez képest">${w.days.map(d=>{const logged=Number.isFinite(d.kcal);const h=logged?Math.max(8,Math.round(d.kcal/max*100)):0;const t=Math.round(d.target/max*100);return `<div class="week-day ${d.weekend?'weekend':''} ${d.today?'today':''}"><i class="target" style="--h:${t}%"></i>${logged?`<i class="bar ${d.kcal<=d.target+60?'within':'over'}" style="--h:${h}%"></i>`:'<i class="gap"></i>'}<b>${logged?String(Math.round(d.kcal)):'·'}</b><span>${d.day}</span>${d.training?'<u title="Edzésnap"></u>':''}</div>`;}).join('')}</div>`;}
function trendek(){const w=weekData[week],s=weekSummary(w);return `<div class="trend-hero"><span class="overline">JÓL MENT A HETEM?</span><div class="trend-week-nav"><button data-week="previous" aria-pressed="${week==='previous'}">‹ Múlt hét</button><strong>${w.label}</strong><button data-week="current" aria-pressed="${week==='current'}" ${week==='current'?'disabled':''}>Ez a hét ›</button></div><div class="trend-big">${s.logged?`<strong>${s.within}<small> / ${s.logged}</small></strong><span>NAP A KERETEDEN BELÜL</span>`:'<strong>—</strong><span>MÉG NINCS NAPLÓZOTT NAP</span>'}</div>${weekBars(w)}<p class="trend-read">${week==='current'?'Három naplózott nap, mindhárom kereten belül. A hét többi része még előtted áll — üresen hagyjuk, nem találgatjuk.':s.weekendDelta>0?`Hétvégén átlagosan ${fmt(s.weekendDelta)} kcal-lal többet ettél, mint hétköznap. Nem hiba — így alakult, és most már látod.`:'Kiegyensúlyozott hét volt.'}</p></div><div class="lf-stats trend-stats"><div><strong>${s.avg?fmt(s.avg):'—'}</strong><small>napi átlag kcal</small></div><div><strong>${w.scoreAvg?`✨ ${w.scoreAvg.toLocaleString('hu-HU')}`:'—'}</strong><small>étkezés-minőség</small></div><div><strong>${w.weightAvg?`${w.weightAvg.toLocaleString('hu-HU')} kg`:'—'}</strong><small>heti súlyátlag</small></div></div><div class="lf-section"><h2>Hosszabb táv</h2><small>7 HÉT</small></div>${horizonChart()}<div class="lf-section"><h2>Mintázatok</h2><small>A MEZO FIGYELI</small></div>${patterns.map(p=>`<button class="konyha-row pattern" data-route="${p.route}">${icon('gem')}<span><strong>${safe(p.title)}</strong><small>${safe(p.state)} · a részletek a Mezo oldalon</small></span><b>↗</b></button>`).join('')}<p class="food-note">A mintázatok kanonikus otthona a Mezo — innen csak odalépsz, nem másolat.</p>`;}
function horizonChart(){const ks=longHorizon.map(r=>r.kcal),ws=longHorizon.map(r=>r.weight);const kmin=Math.min(...ks)-40,kmax=Math.max(...ks)+40,wmin=Math.min(...ws)-.15,wmax=Math.max(...ws)+.15;const x=i=>26+i*286/(longHorizon.length-1);const ky=v=>108-(v-kmin)/(kmax-kmin)*76,wy=v=>108-(v-wmin)/(wmax-wmin)*76;
 return `<figure class="lf-chart horizon"><svg viewBox="0 0 340 150" role="img" aria-label="Heti átlag kalória és súly együtt, hét héten át"><path d="M26 32H312M26 70H312M26 108H312" stroke="#ffffff0d"/><polyline points="${longHorizon.map((r,i)=>`${x(i)},${ky(r.kcal)}`).join(' ')}" fill="none" stroke="#8ed2e8" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${longHorizon.map((r,i)=>`${x(i)},${wy(r.weight)}`).join(' ')}" fill="none" stroke="#d7a7bc" stroke-width="2.5" stroke-dasharray="1 6" stroke-linecap="round"/>${longHorizon.map((r,i)=>`<circle cx="${x(i)}" cy="${wy(r.weight)}" r="2.6" fill="#d7a7bc"/>`).join('')}<text x="26" y="146">${longHorizon[0].week}</text><text x="270" y="146">${longHorizon.at(-1).week}</text></svg><figcaption><span class="dot kcal"></span> heti átlag kcal · <span class="dot weight"></span> heti súlyátlag</figcaption><details><summary>Adatok szövegesen</summary>${longHorizon.map(r=>`<p>${r.week} · ${fmt(r.kcal)} kcal · ${r.weight.toLocaleString('hu-HU')} kg</p>`).join('')}</details></figure>`;}

// --- Kiegészítők ----------------------------------------------------------
function stackPage(){const prog=stackProgress(stack),pct=Math.round(prog.taken/prog.total*100);return `<div class="stack-hero"><div class="stack-ring" style="--stack-progress:${pct}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="stack-ring-track" cx="60" cy="60" r="52" pathLength="100"/><circle class="stack-ring-progress" cx="60" cy="60" r="52" pathLength="100"/></svg><span><strong>${prog.taken}<small> / ${prog.total}</small></strong><b>BEVÉVE MA</b></span></div><div class="stack-hero-copy"><span class="overline">MIT VESZEK BE MA?</span><p>${prog.taken===prog.total?'Minden a helyén. Mára ennyi volt.':'Egy érintés, és pipálva. Ha félrement, még egy érintés visszavonja.'}</p></div></div>${stackZones.map(([zone,label])=>{const rows=stack.items.filter(i=>i.zone===zone);if(!rows.length)return '';return `<div class="lf-section"><h2>${label}</h2><small>${rows.filter(r=>stack.taken.has(r.id)).length} / ${rows.length}</small></div>${rows.map(r=>{const done=stack.taken.has(r.id);return `<button class="stack-row ${done?'done':''}" data-stack-tick="${r.id}" aria-pressed="${done}"><span class="stack-check">${done?'✓':''}</span><span><strong>${safe(r.name)}</strong><small>${safe(r.dose)} · ${safe(r.zoneLabel)}</small></span><b>${done?'VISSZAVONOM':'BEVETTEM'}</b></button>`;}).join('')}`;}).join('')}<div class="lf-section"><h2>Mélyebben</h2></div><button class="konyha-row" data-stack-protocol>${icon('stack')}<span><strong>Protokoll</strong><small>Mit miért szedsz — és ki tette a helyére</small></span><b>↗</b></button><button class="konyha-row" data-stack-manage>${icon('gem')}<span><strong>Kezelés</strong><small>Új elem, adag, időzítés</small></span><b>↗</b></button><button class="konyha-row quiet" data-stack-medication>${icon('moon')}<span><strong>Gyógyszer</strong><small>Most nincs követett gyógyszered</small></span><b>↗</b></button><p class="food-note">Mintaprotokoll. A pipák a demóban élnek, újratöltéskor törlődnek.</p>`;}
const protocolSheet=()=>`<h2 class="sheet-title">A protokollod</h2><p class="sheet-sub">Minden elemnél látod, miért szeded és ki döntött a helyéről.</p>${stack.items.map(r=>`<div class="proto-row">${icon('gem')}<span><strong>${safe(r.name)} · ${safe(r.dose)}</strong><small>${safe(r.zoneLabel)} · ${safe(r.source)}</small><p>${safe(r.why)}</p></span></div>`).join('')}`;
const manageSheet=()=>`<h2 class="sheet-title">Kezelés</h2><p class="sheet-sub">Új elem felvételekor az okos elhelyezés javasol idősávot — te bármikor átteheted.</p><form id="stack-add-form"><label class="lf-field">Mit vennél fel?<input name="name" required placeholder="Pl. Cink"></label><label class="lf-field">Adag<input name="dose" placeholder="Pl. 15 mg"></label><label class="lf-field">Idősáv<select name="zone"><option value="auto" selected>✨ Okos elhelyezés dönti</option>${stackZones.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><button class="sheet-action">Felveszem a protokollba ✓</button></form>`;
const medicationSheet=()=>`${icon('moon')}<h2 class="sheet-title">Gyógyszer</h2><p class="sheet-sub">Most nincs követett gyógyszered — és ezt nem is töltjük ki találgatással. Ha egyszer szükség lesz rá, itt indul: napi ciklus, beadások, emlékeztetők.</p>`;

export function fuelPagesContent(domain,page){if(domain!=='fuel')return null;const view=location.hash.slice(1).split('/')[2]||'';if(page===1)return view==='receptek'?receptekPage():view==='kamra'?kamraPage():konyha();if(page===2)return trendek();if(page===3)return stackPage();return null;}
export function initFuelPages(options){callbacks=options;
 document.querySelector('#sheet')?.addEventListener('close',e=>e.target.classList.remove('glass'));
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
  if(el.dataset.subroute)location.hash=`#fuel/1/${el.dataset.subroute}`;
  if(el.dataset.score)location.hash=`#fuel/0/score/${el.dataset.score}`;
  if(el.dataset.mealOpen)location.hash=`#fuel/0/meal/${el.dataset.mealOpen}`;
  if(el.hasAttribute('data-energy-detail')){callbacks.dialog('A NAPI KERETED',energyDetailHtml());document.querySelector('#sheet').classList.add('glass');}
  if(el.dataset.dim){const [mealId,dimId]=el.dataset.dim.split('|');callbacks.dialog('AI-ÉRTÉKELÉS · SZEMPONT',dimGlassHtml(mealId,dimId));document.querySelector('#sheet').classList.add('glass');}
  if(el.dataset.scoreFeedback){toast(el.dataset.scoreFeedback==='up'?'Köszönöm — ez segít pontosítani.':'Értem. Ezt a visszajelzést is tanulom.');react('connect',1200);}
  if(el.hasAttribute('data-konyha-recipe'))callbacks.dialog('KONYHA · RECEPT',workshopSheet());
  if(el.hasAttribute('data-konyha-pantry'))callbacks.dialog('KONYHA · KAMRA',pantrySheet());
  if(el.dataset.recipeTab||el.dataset.pantryTab){const kind=el.dataset.recipeTab?'recipe':'pantry',value=el.dataset[kind==='recipe'?'recipeTab':'pantryTab'];document.querySelectorAll(`[data-${kind}-pane]`).forEach(p=>p.hidden=p.dataset[kind==='recipe'?'recipePane':'pantryPane']!==value);document.querySelectorAll(`[data-${kind}-tab]`).forEach(t=>t.setAttribute('aria-pressed',String(t===el)));}
  if(el.dataset.workshopGoal){const target=document.querySelector('#workshop-result');if(target)target.innerHTML=`<div class="chat-bubble">Egy ${safe(el.dataset.workshopGoal.toLocaleLowerCase('hu'))} tál: lencsés curry rizzsel. 610 kcal, 31 g fehérje adagonként. Mentsem így, vagy alakítsunk rajta?<span class="chat-time">MŰHELY · MINTAVÁLASZ</span></div><button class="sheet-action" data-workshop-save>Mentem a receptet ✓</button>`;react('connect',2000);}
  if(el.hasAttribute('data-workshop-save')){const saved=addRecipe(recipes,{name:'Lencsés curry',kcal:610,p:31,lines:['Vöröslencse 120 g','Rizs 80 g','Kókusztej 100 ml']});callbacks.closeSheet();toast(saved?'Recept mentve: Lencsés curry':'Ez a recept már megvan.');callbacks.refresh();}
  if(el.dataset.workshopIterate){callbacks.dialog('MŰHELY · ITERÁLÁS',`<div class="chat-bubble">Mit alakítsunk a recepten? Több fehérje, kevesebb szénhidrát, más köret?<span class="chat-time">MŰHELY · DEMÓ</span></div><p class="sheet-sub">A demóban innen a mentés útja ugyanaz, mint az új receptnél.</p>`);}
  if(el.hasAttribute('data-pantry-shot')){const target=document.querySelector('#pantry-photo-result');if(target)target.innerHTML=`<div class="import-preview"><span class="overline">KIOLVASOTT ADATOK · BIZONYTALANSÁGGAL</span><strong>Félzsíros túró · 250 g</strong><small>121 kcal / 100 g · 12 g fehérje · forrás: címkefotó</small><button class="sheet-action" data-pantry-import="Félzsíros túró|250 g|fotó">Felveszem a kamrába ✓</button></div>`;react('connect',2000);}
  if(el.dataset.pantryImport!==undefined&&el.dataset.pantryImport){const [name,amount,src]=el.dataset.pantryImport.split('|');if(pantry.some(p=>p.name===name))toast('Már a polcodon van.');else addPantryItem(pantry,{name,amount,source:src});callbacks.closeSheet();toast(`${name} · a kamrádban`);callbacks.refresh();}
  if(el.dataset.catalogAdd){if(pantry.some(p=>p.name===el.dataset.catalogAdd))toast('Már a polcodon van.');else{addPantryItem(pantry,{name:el.dataset.catalogAdd,amount:'',source:'katalógus'});toast(`${el.dataset.catalogAdd} · a kamrádban`);}callbacks.closeSheet();callbacks.refresh();}
  if(el.dataset.recipe){const r=recipes.find(x=>x.id===el.dataset.recipe);if(r)callbacks.dialog('RECEPT',recipeSheet(r));}
  if(el.dataset.recipeLog){const r=recipes.find(x=>x.id===el.dataset.recipeLog);if(r){callbacks.closeSheet();openFoodFixed(r.name,{kcal:r.kcal,p:r.p,c:Math.round(r.kcal*.45/4),f:Math.round(r.kcal*.3/9),fiber:6},'12:30');}}
  if(el.dataset.pantry){const k=pantry.find(x=>x.id===el.dataset.pantry);if(k)callbacks.dialog('KAMRA',pantryItemSheet(k));}
  if(el.dataset.pantryLog){const k=pantry.find(x=>x.id===el.dataset.pantryLog);if(k){callbacks.closeSheet();openFoodFixed(k.name,{kcal:Math.round(k.kcal100*1.5),p:Math.round((k.p100||0)*1.5),c:20,f:5,fiber:1},'16:00');}}
  if(el.dataset.pantryRemove){removePantryItem(pantry,el.dataset.pantryRemove);callbacks.closeSheet();toast('Levéve a polcról.');callbacks.refresh();}
  if(el.dataset.week){week=el.dataset.week;callbacks.refresh();}
  if(el.dataset.stackTick){const taken=toggleIntake(stack,el.dataset.stackTick);if(taken!==null){toast(taken?'Bevéve. Még egy érintés visszavonja.':'Visszavonva.');react('connect',1200);callbacks.refresh();}}
  if(el.hasAttribute('data-stack-protocol'))callbacks.dialog('KIEGÉSZÍTŐK',protocolSheet());
  if(el.hasAttribute('data-stack-manage'))callbacks.dialog('KIEGÉSZÍTŐK',manageSheet());
  if(el.hasAttribute('data-stack-medication'))callbacks.dialog('KIEGÉSZÍTŐK',medicationSheet());
 });
 document.addEventListener('submit',e=>{const data=new FormData(e.target);
  if(e.target.id==='recipe-manual-form'){e.preventDefault();const saved=addRecipe(recipes,{name:String(data.get('name')).trim(),kcal:Number(data.get('kcal')),p:Number(data.get('p'))});callbacks.closeSheet();toast(saved?`Recept mentve: ${saved.name}`:'Nézd meg a név és a számok mezőit.');callbacks.refresh();}
  if(e.target.id==='recipe-link-form'){e.preventDefault();const target=document.querySelector('#recipe-link-result');if(target)target.innerHTML=`<div class="import-preview"><span class="overline">KINYERT RECEPT · ELŐNÉZET</span><strong>Sült zöldséges bulgur</strong><small>540 kcal / adag · 22 g fehérje · a link alapján, becsléssel</small><button class="sheet-action" data-link-recipe-save>Mentem a receptet ✓</button></div>`;react('connect',2000);}
  if(e.target.id==='pantry-link-form'){e.preventDefault();const target=document.querySelector('#pantry-link-result');if(target)target.innerHTML=`<div class="import-preview"><span class="overline">KINYERT ADATOK · ELŐNÉZET</span><strong>Földimogyoró-krém · 350 g</strong><small>588 kcal / 100 g · 25 g fehérje · forrás: link</small><button class="sheet-action" data-pantry-import="Földimogyoró-krém|350 g|link">Felveszem a kamrába ✓</button></div>`;react('connect',2000);}
  if(e.target.id==='stack-add-form'){e.preventDefault();const zoneChoice=String(data.get('zone')),auto=zoneChoice==='auto',zone=auto?'este':zoneChoice,zoneLabel=Object.fromEntries(stackZones)[zone];const item=addStackItem(stack,{name:String(data.get('name')).trim(),dose:String(data.get('dose')).trim(),zone,zoneLabel});callbacks.closeSheet();toast(item?`${item.name} · ${auto?'az okos elhelyezés estére tette':zoneLabel.toLocaleLowerCase('hu')}`:'Add meg a nevét.');callbacks.refresh();}
 });
 document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.hasAttribute('data-link-recipe-save')){const saved=addRecipe(recipes,{name:'Sült zöldséges bulgur',kcal:540,p:22,lines:['Bulgur 90 g','Sült zöldségek 200 g','Fetakocka 40 g']});callbacks.closeSheet();toast(saved?'Recept mentve: Sült zöldséges bulgur':'Ez a recept már megvan.');callbacks.refresh();}});
 document.querySelector('#restart')?.addEventListener('click',()=>{recipes=createRecipes();pantry=createPantry();stack=createStack();week='current';});
}
